  ["feature.bonus-proficiency.psa2014.cleric.strength-psa.1"]={title="Bonus Proficiency",subtitle="Caracteristica - PSA - 2014",body="Pagina: 26\n\nAlso at 1st level, you gain proficiency with heavy armor."},
